function safe(name) {
  try { return $(name).first().json || {}; } catch (e) { return { _error: true, _message: String(e.message || e) }; }
}

const backup = safe('Get Backup Status');
const storage = safe('Get Storage Status');
const docker = safe('Get Docker Status');
const pg = safe('Get Postgres Version');
const immich = safe('Get Immich Status');
const prevRows = (() => { try { return $('Get Previous States').all().map(i => i.json).filter(Boolean); } catch (e) { return []; } })();
const metaRows = (() => { try { return $('Get Advisor Meta').all().map(i => i.json).filter(Boolean); } catch (e) { return []; } })();

let backup_status = 'unknown';
if (backup && backup.healthy === true) backup_status = 'healthy';
else if (backup && backup.healthy === false) backup_status = 'degraded';

let system_status = 'healthy';
if (storage && storage.healthy === false) system_status = 'degraded';
if (immich && immich.overall_status && immich.overall_status !== 'healthy') system_status = 'degraded';
if (docker && docker.healthy === false) system_status = 'degraded';

const previous_by_component = {};
for (const r of prevRows) {
  if (!r.component) continue;
  previous_by_component[r.component] = r;
}

const meta_by_component = {};
for (const r of metaRows) {
  if (!r.component) continue;
  meta_by_component[r.component] = r;
}

const postgres_version = pg.server_version || pg.version || null;

return [{
  json: {
    evaluate_request: {
      context: {
        backup_status,
        system_status,
        storage_healthy: storage.healthy === true,
        docker_healthy: docker.healthy === true,
        immich_status: immich.overall_status || 'unknown',
      },
      docker_containers: Array.isArray(docker.containers) ? docker.containers : [],
      postgres_version,
      previous_by_component,
      meta_by_component,
    },
  },
}];

const result = $('Call Update Advisor').first().json || {};
const components = Array.isArray(result.components) ? result.components : [];
const events = Array.isArray(result.events) ? result.events : [];
const metaUpdates = result.meta_updates || {};
const now = new Date().toISOString();

const persistItems = components.map((c) => ({
  json: {
    kind: 'persist',
    checked_at: now,
    component: c.component,
    installed_version: c.installed_version ?? null,
    available_version: c.available_version ?? null,
    update_type: c.update_type ?? null,
    risk: c.risk ?? null,
    recommendation: c.recommendation ?? null,
    security_signal: !!c.security_signal,
    breaking_change_signal: !!c.breaking_change_signal,
    update_available: !!c.update_available,
    source: c.source ?? null,
    source_status: c.source_status ?? null,
    details: c.details || {},
  },
}));

const metaItems = Object.entries(metaUpdates).map(([component, m]) => ({
  json: {
    kind: 'meta',
    component,
    source_fail_streak: Number(m.source_fail_streak || 0),
    last_event_fingerprint: m.last_event_fingerprint ?? null,
    last_installed_version: m.last_installed_version ?? null,
    last_available_version: m.last_available_version ?? null,
    last_recommendation: m.last_recommendation ?? null,
  },
}));

const eventItems = events.map((ev) => ({
  json: {
    kind: 'event',
    should_emit: true,
    source: 'update_advisor',
    severity: ev.severity || 'info',
    component: 'updates',
    event: ev.event,
    status: ev.recommendation || 'advisory',
    timestamp: now,
    message: ev.message || `Update advisor: ${ev.event}`,
    details: {
      target_component: ev.component,
      installed_version: ev.installed_version ?? null,
      available_version: ev.available_version ?? null,
      update_type: ev.update_type ?? null,
      risk: ev.risk ?? null,
      recommendation: ev.recommendation ?? null,
      security_signal: !!ev.security_signal,
      breaking_change_signal: !!ev.breaking_change_signal,
      advisory_only: true,
      executed_updates: false,
    },
    requires_attention: (ev.severity || 'info') !== 'info',
    suggested_action: ev.recommendation === 'defer'
      ? 'Adiar atualização até backup/sistema saudáveis.'
      : 'Revisar recomendação; nenhuma alteração automática será feita.',
    correlation_id: `update-advisor:${ev.component}:${ev.event}`,
  },
}));

if (!persistItems.length) {
  persistItems.push({ json: { kind: 'persist', skip: true } });
}

return [...persistItems, ...metaItems, ...eventItems];

