={{
(() => {
  if ($json.skip) return 'SELECT 1 AS skipped;';
  const esc = (v) => String(v ?? '').replace(/'/g, "''");
  const comp = esc($json.component).slice(0, 100);
  if (!comp) return 'SELECT 1 AS skipped_empty;';
  const details = JSON.stringify($json.details || {}).replace(/'/g, "''");
  const nul = (v) => (v === null || v === undefined || v === '') ? 'NULL' : `'${esc(v)}'`;
  return `
INSERT INTO update_advisor_state (
  component, installed_version, available_version, update_type, risk, recommendation,
  security_signal, breaking_change_signal, update_available, source, source_status, checked_at, details
) VALUES (
  '${comp}',
  ${nul($json.installed_version)},
  ${nul($json.available_version)},
  ${nul($json.update_type)},
  ${nul($json.risk)},
  ${nul($json.recommendation)},
  ${$json.security_signal ? 'true' : 'false'},
  ${$json.breaking_change_signal ? 'true' : 'false'},
  ${$json.update_available ? 'true' : 'false'},
  ${nul($json.source)},
  ${nul($json.source_status)},
  '${esc($json.checked_at)}'::timestamptz,
  '${details}'::jsonb
);`;
})()
}}

