(() => {
  const esc = (v) => String(v ?? '').replace(/'/g, "''");
  const comp = esc($json.component).slice(0, 100);
  const nul = (v) => (v === null || v === undefined || v === '') ? 'NULL' : `'${esc(v)}'`;
  return `
INSERT INTO update_advisor_meta (
  component, source_fail_streak, last_event_fingerprint,
  last_installed_version, last_available_version, last_recommendation, updated_at
) VALUES (
  '${comp}',
  ${Number($json.source_fail_streak || 0)},
  ${nul($json.last_event_fingerprint)},
  ${nul($json.last_installed_version)},
  ${nul($json.last_available_version)},
  ${nul($json.last_recommendation)},
  now()
)
ON CONFLICT (component) DO UPDATE SET
  source_fail_streak = EXCLUDED.source_fail_streak,
  last_event_fingerprint = EXCLUDED.last_event_fingerprint,
  last_installed_version = EXCLUDED.last_installed_version,
  last_available_version = EXCLUDED.last_available_version,
  last_recommendation = EXCLUDED.last_recommendation,
  updated_at = now();`;
})()
}}

